<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../services/api';import type{BorrowRequest}from'../types/archive';const items=ref<BorrowRequest[]>([]);async function load(){items.value=(await api.get('/borrows')).data.items}async function act(id:string,action:string){await api.post(`/borrows/${id}/${action}`,action==='review'?{approved:true}:{});await load()}onMounted(load)</script>
<template><el-card><template #header><b>借阅申请与流转</b></template><el-steps :active="3" simple><el-step title="申请"/><el-step title="审批"/><el-step title="借出"/><el-step title="续借/归还"/></el-steps><el-table :data="items"><el-table-column prop="case_id" label="案卷"/><el-table-column prop="applicant_id" label="申请人"/><el-table-column prop="purpose" label="用途"/><el-table-column prop="due_at" label="应还时间"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="s"><el-button v-if="s.row.status==='pending'" link @click="act(s.row.id,'review')">批准</el-button><el-button v-if="s.row.status==='approved'" link @click="act(s.row.id,'checkout')">借出</el-button><el-button v-if="['checked_out','overdue'].includes(s.row.status)" link @click="act(s.row.id,'return')">归还</el-button></template></el-table-column></el-table></el-card></template>
